generated_sql:
SELECT DISTINCT m.Maker, ml.Model 
FROM model_list ml 
JOIN car_makers m ON ml.Maker = m.Id;

SELECT c.CountryName, c.CountryId
FROM countries c
INNER JOIN car_makers cm ON c.CountryId = cm.Country;

SELECT Cylinders, MAX(Accelerate) AS Max_Accelerate
FROM cars_data
GROUP BY Cylinders;

SELECT DestAirport AS AirportCode FROM (
    SELECT DestAirport, COUNT(*) AS FlightCount FROM flights GROUP BY DestAirport
) ORDER BY FlightCount ASC LIMIT 1;

SELECT Document_Name, Template_ID 
FROM Documents 
WHERE LOWER(Document_Description) LIKE '%w%';

SELECT Version_Number, Template_Type_Code 
FROM Templates 
WHERE Version_Number > 5;

SELECT Paragraph_ID, Document_ID, Paragraph_Text, Other_Details 
FROM Paragraphs 
WHERE LOWER(Paragraph_Text) = LOWER('Korea ');

SELECT MAX(Final_Table_Made) AS max_final_tables_made
FROM poker_player
WHERE Earnings < 200000;

SELECT AVG(CAST(d.age AS REAL)) AS average_age
FROM Dogs d
JOIN Treatments t ON d.dog_id = t.dog_id;

SELECT professional_id, first_name || ' ' || last_name AS role, email_address
FROM Professionals
WHERE professional_id NOT IN (
    SELECT DISTINCT professional_id
    FROM Treatments
);

SELECT first_name, last_name, email_address
FROM Owners
WHERE LOWER(state) LIKE '%north%';

SELECT Citizenship, MAX(Net_Worth_Millions) AS Max_Net_Worth
FROM singer
GROUP BY Citizenship;
